const auth = $request.headers.authorization || $request.headers.Authorization || '';
const token = String(auth).replace(/^Bearer\s+/i, '').trim();
if (!token || token.split('.').length < 2) {
  return [{ json: { success: false, message: 'Unauthorized', statusCode: 401 } }];
}
let payload = {};
try {
  const raw = token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
  payload = JSON.parse(Buffer.from(raw + '='.repeat((4 - raw.length % 4) % 4), 'base64').toString('utf8'));
} catch (e) {
  return [{ json: { success: false, message: 'Unauthorized', statusCode: 401 } }];
}
const userId = Number(payload.id || payload.userId || payload.sub);
const addressId = Number($json.body?.address_id || $json.body?.id || $json.address_id);
if (!userId) return [{ json: { success: false, message: 'Unauthorized', statusCode: 401 } }];
if (!addressId) return [{ json: { success: false, message: 'address_id required', statusCode: 400 } }];
return [{ json: { user_id: userId, address_id: addressId } }];

