UPDATE `address` SET is_current = 1 WHERE id = {{ $json.address_id }} AND user_id = {{ $json.user_id }};
SELECT id, user_id, title, address, details, city, postal_code, latitude, longitude, is_current, created_at
FROM `address`
WHERE user_id = {{ $json.user_id }} AND id = {{ $json.address_id }}
LIMIT 1;
